import React from 'react';

import * as RadixTooltip from '@radix-ui/react-tooltip';

import {
  TOOLTIP_COLLISION_PADDING,
  TOOLTIP_DELAY_MS,
  TOOLTIP_SIDE_OFFSET,
} from './Tooltip.constants';
import {
  getTooltipTextAlign,
  StyledTooltipContent,
  StyledTooltipRoot,
  StyledTooltipText,
  tooltipArrowStyle,
} from './Tooltip.styles';
import type { TooltipProps } from './Tooltip.types';

export const Tooltip = React.forwardRef<HTMLDivElement, TooltipProps>(
  (
    {
      position = 'bottom',
      className,
      children,
      content,
      open,
      onOpenChange,
      defaultOpen,
      ...contentProps
    },
    forwardedRef,
  ) => (
    <StyledTooltipRoot ref={forwardedRef} className={className}>
      <RadixTooltip.Provider delayDuration={TOOLTIP_DELAY_MS}>
        <RadixTooltip.Root
          defaultOpen={defaultOpen}
          onOpenChange={onOpenChange}
          open={open}
        >
          <RadixTooltip.Trigger asChild>{children}</RadixTooltip.Trigger>
          <RadixTooltip.Portal>
            <RadixTooltip.Content
              {...contentProps}
              arrowPadding={0}
              asChild
              collisionPadding={TOOLTIP_COLLISION_PADDING}
              side={position}
              sideOffset={TOOLTIP_SIDE_OFFSET}
            >
              <StyledTooltipContent $textAlign={getTooltipTextAlign(position)}>
                <StyledTooltipText>{content}</StyledTooltipText>
                <RadixTooltip.Arrow style={tooltipArrowStyle} />
              </StyledTooltipContent>
            </RadixTooltip.Content>
          </RadixTooltip.Portal>
        </RadixTooltip.Root>
      </RadixTooltip.Provider>
    </StyledTooltipRoot>
  ),
);

Tooltip.displayName = 'Tooltip';
